use std::sync::{Arc, Mutex};

use axum::routing::post;
use axum::Router;

pub mod handlers;
pub mod repository;

#[derive(Clone)]
pub struct AppState {
    pub accounts: Arc<Mutex<repository::AccountRepository>>,
}

pub fn build_router() -> Router {
    let state = AppState {
        accounts: Arc::new(Mutex::new(repository::AccountRepository::new())),
    };
    Router::new()
        .route("/withdraw", post(handlers::withdraw))
        .with_state(state)
}

