use axum::extract::State;
use axum::http::StatusCode;
use axum::Json;
use serde::Deserialize;
use serde_json::{json, Value};

use crate::AppState;

#[derive(Deserialize)]
pub struct WithdrawBody {
    pub account: String,
    pub amount: i64,
}

pub async fn withdraw(
    State(state): State<AppState>,
    Json(body): Json<WithdrawBody>,
) -> (StatusCode, Json<Value>) {
    match state.accounts.lock().unwrap().withdraw(&body.account, body.amount) {
        Ok(balance) => (StatusCode::OK, Json(json!({"balance": balance}))),
        // BUG: every error becomes 500 - a missing account and an overdraft
        // both look like server errors to the client.
        Err(err) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({"error": format!("{err:?}")})),
        ),
    }
}

