use std::collections::HashMap;

#[derive(Debug, PartialEq)]
pub enum WithdrawError {
    NotFound,
    InsufficientFunds,
}

pub struct AccountRepository {
    balances: HashMap<String, i64>,
}

impl AccountRepository {
    pub fn new() -> Self {
        let mut balances = HashMap::new();
        balances.insert("alice".to_string(), 100);
        AccountRepository { balances }
    }

    /// Withdraw `amount`; returns the new balance, or a typed error.
    pub fn withdraw(&mut self, account: &str, amount: i64) -> Result<i64, WithdrawError> {
        let balance = self.balances.get_mut(account).ok_or(WithdrawError::NotFound)?;
        if amount > *balance {
            return Err(WithdrawError::InsufficientFunds);
        }
        *balance -= amount;
        Ok(*balance)
    }
}

