use axum::body::{to_bytes, Body};
use axum::http::{Request, StatusCode};
use serde_json::Value;
use tower::ServiceExt;

async fn send(app: axum::Router, method: &str, uri: &str, body: Option<&str>) -> (StatusCode, Value) {
    let mut builder = Request::builder().method(method).uri(uri);
    let request = match body {
        Some(b) => builder
            .header("content-type", "application/json")
            .body(Body::from(b.to_string()))
            .unwrap(),
        None => builder.body(Body::empty()).unwrap(),
    };
    let res = app.oneshot(request).await.unwrap();
    let status = res.status();
    let bytes = to_bytes(res.into_body(), usize::MAX).await.unwrap();
    let value = if bytes.is_empty() {
        Value::Null
    } else {
        serde_json::from_slice(&bytes).unwrap_or(Value::Null)
    };
    (status, value)
}

#[tokio::test]
async fn status_mapping() {
    let app = webapp::build_router();

    let (status, body) = send(app.clone(), "POST", "/withdraw",
        Some(r#"{"account": "alice", "amount": 40}"#)).await;
    assert_eq!(status, StatusCode::OK, "{body}");
    assert_eq!(body["balance"], 60);

    let (status, _) = send(app.clone(), "POST", "/withdraw",
        Some(r#"{"account": "ghost", "amount": 10}"#)).await;
    assert_eq!(status, StatusCode::NOT_FOUND, "missing account must be 404");

    let (status, _) = send(app, "POST", "/withdraw",
        Some(r#"{"account": "alice", "amount": 100000}"#)).await;
    assert_eq!(status, StatusCode::CONFLICT, "overdraft must be 409");
}

